"use client";

import { useEffect, useState } from "react";
import AppLayout from "@/components/AppLayout";
import { useAuth } from "@/contexts/AuthContext";

export default function DashboardPage() {
  const { user, loading } = useAuth();
  const [news, setNews] = useState([]);
  const [videos, setVideos] = useState([]);
  const [newsError, setNewsError] = useState(false);
  const [videoError, setVideoError] = useState(false);

  useEffect(() => {
    fetch("/api/news")
      .then((r) => r.json())
      .then((data) => {
        if (data.error) throw new Error();
        setNews(data.articles);
      })
      .catch(() => setNewsError(true));

    fetch("/api/youtube")
      .then((r) => r.json())
      .then((data) => {
        if (data.error) throw new Error();
        setVideos(data.items);
      })
      .catch(() => setVideoError(true));
  }, []);

  if (loading)
    return (
      <div className="min-h-screen flex items-center justify-center">
        Loading…
      </div>
    );

  return (
    <AppLayout>
      <div className="grid grid-cols-3 gap-6">
        {/* Welcome panel */}
        <div className="col-span-2 bg-white p-6 rounded shadow">
          <h1 className="text-3xl font-bold mb-2">
            Welcome, {user?.username}!
          </h1>
          <p>This is your personalized Huddle dashboard.</p>
        </div>

        <div className="space-y-6">
          {/* Top Indian Headlines */}
          <div className="bg-white p-4 rounded shadow">
            <h2 className="font-semibold mb-3">Top Indian Headlines</h2>
            {newsError && <p className="text-red-500">Error loading news.</p>}
            {!newsError &&
              news.map((a, i) => (
                <div key={i} className="flex gap-3 mb-4">
                  {a.urlToImage && (
                    <img
                      src={a.urlToImage}
                      alt={a.title}
                      className="w-16 h-16 object-cover rounded"
                    />
                  )}
                  <div>
                    <a
                      href={a.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="font-medium block"
                    >
                      {a.title}
                    </a>
                    <p className="text-sm text-gray-600">{a.source.name}</p>
                  </div>
                </div>
              ))}
          </div>

          {/* Entertainment Reels */}
          <div className="bg-white p-4 rounded shadow">
            <h2 className="font-semibold mb-3">Entertainment Reels</h2>
            {videoError && (
              <p className="text-red-500">Error loading videos.</p>
            )}
            {!videoError &&
              videos.map((v, i) => (
                <a
                  key={i}
                  href={`https://www.youtube.com/watch?v=${v.id.videoId}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="flex gap-3 mb-4"
                >
                  <img
                    src={v.snippet.thumbnails.default.url}
                    alt={v.snippet.title}
                    className="w-16 h-16 object-cover rounded"
                  />
                  <div>
                    <p className="font-medium">{v.snippet.title}</p>
                    <p className="text-sm text-gray-600">
                      {v.snippet.channelTitle}
                    </p>
                  </div>
                </a>
              ))}
          </div>
        </div>
      </div>
    </AppLayout>
  );
}
